# ---------------------------------------------------------------------------------------------------------------------
# VECTOR
# ---------------------------------------------------------------------------------------------------------------------
locals {
  vector_enabled = (
    var.vector_enabled != null
    ? var.vector_enabled
    : lookup(var.vector_enabled_cluster_types, local.cluster_type, true)
  )
}

module "vector" {
  #source = "crow.infrastructure.immuta.io/internal/monitoring-vector/kubernetes"
  #version = "1.2.1"
  source = "/Users/steve.briggs/projects/operations/terraform/internal-modules/kubernetes/monitoring/vector"

  count  = local.vector_enabled ? 1 : 0

  providers = {
    kubernetes = kubernetes.local-cluster
    helm       = helm.local-cluster
  }

  chart_version               = var.vector_chart_version
  image                       = var.vector_image
  image_tag_version           = var.vector_image_tag
  replicas                    = var.vector_replicas
  resources_requests          = var.vector_resource_requests
  resources_limits            = var.vector_resource_limits
  datadog_site                = var.vector_datadog_site
  datadog_api_key_vault_path  = var.vector_datadog_api_key_vault_path
  audit_drop_patterns         = var.vector_audit_drop_patterns
  email_redaction_enabled     = var.vector_email_redaction_enabled
  email_redaction_replacement = var.vector_email_redaction_replacement
  email_redaction_dry_run     = var.vector_email_redaction_dry_run

  bearer_token_redaction_enabled            = var.vector_bearer_token_redaction_enabled
  bearer_token_redaction_dry_run            = var.vector_bearer_token_redaction_dry_run
  bearer_token_redaction_replacement        = var.vector_bearer_token_redaction_replacement
  bearer_token_redaction_services           = var.vector_bearer_token_redaction_services
  bearer_token_redaction_exclusion_patterns = var.vector_bearer_token_redaction_exclusion_patterns

  aws_access_key_redaction_enabled              = var.vector_aws_access_key_redaction_enabled
  aws_access_key_redaction_dry_run              = var.vector_aws_access_key_redaction_dry_run
  aws_access_key_redaction_replacement          = var.vector_aws_access_key_redaction_replacement
  aws_access_key_redaction_services             = var.vector_aws_access_key_redaction_services
  aws_access_key_redaction_exclusion_patterns   = var.vector_aws_access_key_redaction_exclusion_patterns
  aws_access_key_redaction_exclusion_attributes = var.vector_aws_access_key_redaction_exclusion_attributes

  jwt_redaction_enabled            = var.vector_jwt_redaction_enabled
  jwt_redaction_dry_run            = var.vector_jwt_redaction_dry_run
  jwt_redaction_replacement        = var.vector_jwt_redaction_replacement
  jwt_redaction_services           = var.vector_jwt_redaction_services
  jwt_redaction_exclusion_patterns = var.vector_jwt_redaction_exclusion_patterns

  additional_config = var.vector_additional_config

  external_secrets_cluster_store_name = var.vector_external_secrets_cluster_store_name

  depends_on = [
    module.cilium,
    module.external_secrets,
  ]
}

resource "terraform_data" "vector_validate" {
  count = local.vector_enabled ? 1 : 0

  lifecycle {
    precondition {
      condition     = local.external_secrets_enabled
      error_message = "vector can only be enabled if external-secrets is also enabled"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# REQUIRED PARAMETERS
# These variables must be set.
# ---------------------------------------------------------------------------------------------------------------------
variable "vector_chart_version" {
  description = "Version of vector helm chart"
  type        = string
  default     = ""
  validation {
    condition     = var.vector_chart_version == "" && local.vector_enabled ? false : true
    error_message = "vector_chart_version must be set when vector is enabled"
  }
}

variable "vector_image_tag" {
  description = "Vector image tag"
  type        = string
  default     = ""
  validation {
    condition     = var.vector_image_tag == "" && local.vector_enabled ? false : true
    error_message = "vector_image_tag must be set when vector is enabled"
  }
}

variable "vector_datadog_site" {
  description = "Datadog site for vector sinks (e.g. datadoghq.com)"
  type        = string
  default     = "datadoghq.com"
  validation {
    condition     = var.vector_datadog_site == "" && local.vector_enabled ? false : true
    error_message = "vector_datadog_site must be set when vector is enabled"
  }
}

variable "vector_datadog_api_key_vault_path" {
  description = "Vault path for the Datadog API key (consumed by ExternalSecret in vector ns)"
  type        = string
  default     = "secret/data/saas/infrastructure/datadog-api-key"
